return ['domain'=>'press-permit-core','plural-forms'=>'nplurals=1; plural=0;','language'=>'yor','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:58+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions jẹ ki o le mu tabi kọ iraye si awọn ifiweranṣẹ, awọn oju-iwe, awọn ẹka, awọn afi ati diẹ sii.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'Ṣatunkọ Tag fun Gbogbo Awọn Iru Ifiweranṣẹ','Edit Tag for Posts'=>'Ṣatunkọ Tag fun Awọn Ifiweranṣẹ','Advanced Custom Fields'=>'Awọn Ẹka Aṣelọpọ Ti a ṣe adani ti o ni ilọsiwaju','Control front-end access to Field Groups with advanced permission management.'=>'Ṣakoso iraye si iwaju si Awọn Ẹgbẹ Ọrọ pẹlu iṣakoso igbanilaaye to ti ni ilọsiwaju.','Control access to Field Groups'=>'Ṣakoso iraye si Awọn Ẹka Ẹrọ','Front-end visibility restrictions'=>'Iwọn ihamọ irisi iwaju','Integration with permission groups'=>'Isopọpọ pẹlu awọn ẹgbẹ aṣẹ','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Ibaṣepọ pẹlu Ṣatunkọ Awọn aṣẹ ni Beaver Builder.','Beaver editor integration'=>'Ibaṣepọ olootu Beaver','Widget-level permission controls'=>'Iṣakoso aṣẹ ipele Widget','Template access restrictions'=>'Ihamọ iraye si awoṣe','bbPress Forums'=>'bbPress Forums','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Awọn igbanilaaye pataki fun forum fun bbPress pẹlu iṣakoso alaye lori iraye si forum ati ikopa.','Forum-specific permissions'=>'Awọn aṣẹ pato fun forum','Topic creation restrictions'=>'Ìdènà ìdàgbàsókè àkòrí','Forum access controls'=>'Àwọn ìṣàkóso iraye sí fọ́ọ̀mù','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Yàn awọn igbanilaaye ifiweranṣẹ ati ọrọ si awọn ẹgbẹ BuddyPress fun iṣakoso akoonu ti o ni ilọsiwaju.','Assign post permissions to BuddyPress groups'=>'Yàn àṣẹ ìkọ̀wé fún àwọn ẹgbẹ́ BuddyPress','Assign term permissions to BuddyPress groups'=>'Yàn àṣẹ ẹ̀ka fún àwọn ẹgbẹ́ BuddyPress','Group-based content permissions'=>'Àwọn àṣẹ akoonu tó da lori ẹgbẹ́','CMS Tree View'=>'Ìwòpọ́ Ibi Iṣẹ CMS','Compatibility with Edit Permissions in CMS Tree View.'=>'Ìbáṣepọ̀ pẹ̀lú Ṣàtúnṣe Àṣẹ ní Ibi Iṣẹ CMS.','Permission-aware tree view'=>'Ìwòpọ́ igi tí ń mọ̀ àṣẹ','Hierarchical content controls'=>'Àwọn ìṣàkóso akoonu tó ni ìbáṣepọ̀','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Ìbáṣepọ̀ pẹ̀lú Ṣàtúnṣe Àṣẹ ní Elementor.','Elementor editor integration'=>'Ìkànsí olùdásílẹ̀ Elementor','The Events Calendar'=>'Kálẹ́ńdà Àwọn Íṣẹ́lẹ̀','Apply permission controls to events and event-related content.'=>'Lò àwọn ìṣàkóso àṣẹ sí àwọn íṣẹ́lẹ̀ àti akoonu tí ó ní ibáṣepọ̀ pẹ̀lú íṣẹ́lẹ̀.','Event post permissions'=>'Àwọn àṣẹ ìkọ̀wé íṣẹ́lẹ̀','Event taxonomy controls'=>'Àwọn ìṣàkóso ẹ̀ka ìṣẹ́lẹ̀','Nested Pages'=>'Àwọn Ìwé Nẹ́tẹ́dì','Compatibility with Edit Permissions in Nested Pages.'=>'Ìbáṣepọ̀ pẹ̀lú Ṣàtúnṣe Àṣẹ ní Àwọn Ìwé Nẹ́tẹ́dì.','Permission-aware nested view'=>'Wiwo ti a mọ nipa aṣẹ','Quick edit integration'=>'Iṣọpọ ṣiṣatunkọ yarayara','PublishPress Statuses'=>'Ipo PublishPress','Compatibility with PublishPress Statuses plugin.'=>'Ibamu pẹlu afikun Ipo PublishPress.','Custom status permissions'=>'Aṣẹ ipo aṣa','Workflow-specific access controls'=>'Iṣakoso wiwọle ti o da lori iṣẹ','Status-based editing capabilities'=>'Agbara ṣiṣatunkọ ti o da lori ipo','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'Ṣ lọọgan awọn esi wiwa da lori Awọn igbanilaaye Wiwo fun iwari akoonu to ni aabo.','Search result filtering'=>'Ìfihàn àwárí abajade','Permission-aware indexing'=>'Ínàkó aṣẹ ti a mọ','Secure content discovery'=>'Ìkànsí akoonu to ni aabo','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Ibamu pẹlu ìfihàn ọrọ SearchWP fun awọn agbara àwárí to ti ni ilọsiwaju.','Permission-aware search results'=>'Àbájáde àwárí ti a mọ nipa aṣẹ','Term-based filtering'=>'Ìfihàn ti o da lori ọrọ','Advanced search controls'=>'Iṣakoso àwárí to ti ni ilọsiwaju','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Lo awọn iṣakoso aṣẹ si awọn ọja WooCommerce ati awọn ẹka ọja.','Product permissions'=>'Aṣẹ ọja','Product category controls'=>'Iṣakoso ẹka ọja','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Atilẹyin multilingual pẹlu iṣọpọ igbanilaaye kọja awọn itumọ akoonu.','Permission synchronization across translations'=>'Iṣọpọ igbanilaaye kọja awọn itumọ','Language-specific content access'=>'Iwọle akoonu pato ede','Multilingual permission management'=>'Iṣakoso igbanilaaye pupọ ede','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Yọ awọn ifiweranṣẹ ti a ṣe idiwọ kuro ninu awọn XML sitemaps lati pa awọn iṣiro SEO to pe.','Sitemap filtering for restricted content'=>'Iṣ lọọgan sitemaps fun akoonu ti a ṣe idiwọ','Search engine visibility controls'=>'Iṣakoso wiwo ẹrọ iṣawari','Permission-aware XML sitemaps'=>'XML sitemaps ti o ni imọ si igbanilaaye','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Ibarapọ pẹlu oluṣelọpọ YooTheme ati awọn igbanilaaye ọrọ.','Builder interface compatibility'=>'Ibarapọ oju-iwe oluṣelọpọ','Term permission integration'=>'Iṣọpọ igbanilaaye ọrọ','Template access controls'=>'Iṣakoso iwọle àwoṣe','Viewing'=>'Wiwo','Access Circles'=>'Iwọle Awọn iyika','Editing Permissions'=>'Ṣiṣatunkọ Awọn igbanilaaye','Compatibility Pack'=>'Pakà Ibarapọ','Teaser'=>'Ìfihàn','File Access'=>'Ìforúkọsílẹ Fáìlì','Membership'=>'Ìjọpọ','User Posts'=>'Àwọn Ìwé Àtẹ̀jáde Olumulo','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Awọn Iyika Wiwo ati Awọn Iyika Iwe iroyin dènà iraye si akoonu ti ko jẹ ti awọn ọmọ ẹgbẹ ẹgbẹ miiran.','Post-specific and category-specific permissions for creation and editing.'=>'Àwọn ìyàtọ̀ pato fún ìfarahàn àti ṣiṣatunkọ fún ìwé-ìtẹ́wọ́gbà àtẹ̀jáde.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Isopọ pẹlu ACF, bbPress, BuddyPress, Relevanssi, WPML ati awọn plugin miiran; atilẹyin Multisite ti o ni ilọsiwaju.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'Ninu iwaju aaye, fihan ọrọ teaser fun awọn ifiweranṣẹ ti ko le ka dipo ki o pa wọn mọ.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Dènà awọn ibeere faili taara da lori iraye si olumulo si oju-iwe ti faili ti wa ni asopọ si.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'Iwọn akoko iraye si awọn adani nipasẹ idaduro tabi ipari Membership Ẹgbẹ Igbani.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Ṣẹda laifọwọyi oju-iwe fun ọkọọkan awọn olumulo ti awọn ipa ti a ṣalaye. Ni ibamu pẹlu ọpọlọpọ awọn plugin Team / Staff.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Awọn Iyika Wiwo ati Awọn Iyika Iwe iroyin dènà iraye si akoonu ti ko jẹ ti awọn ọmọ ẹgbẹ ẹgbẹ miiran. Ẹnikẹni WP Role, Ẹgbẹ BuddyPress tabi Ẹgbẹ aṣa le jẹ ami bi Iyika fun awọn iru ifiweranṣẹ ti a ṣalaye.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Ṣe atilẹyin awọn igbanilaaye pato akoonu fun ṣiṣatunkọ, iforukọsilẹ ọrọ ati yiyan obi oju-iwe. Ni apapọ pẹlu awọn modulu miiran, ṣe atilẹyin awọn ipo ṣiṣiṣẹ, PublishPress ati PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Fi ibamu tabi isopọ pẹlu ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, ọpọlọpọ awọn plugin miiran. Ṣeto eyikeyi Ẹgbẹ BuddyPress gẹgẹbi Ẹgbẹ Awọn igbanilaaye. Fun multisite, pese Awọn Ẹgbẹ Igbanilaaye ni gbogbo nẹtiwọọki.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'Ninu iwaju aaye, rọpo akoonu ti ko le ka pẹlu ọrọ asopọ. Le ṣee mu ṣiṣẹ fun eyikeyi iru ifiweranṣẹ. Awọn filita aṣa ni a pese ṣugbọn ko si eto pataki ti a nilo fun lilo ipilẹ.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'Ṣ lọọgan iraye si faili taara, da lori iraye si olumulo si ifiweranṣẹ(ṣ) ti faili ti wa ni asopọ si. Ko si iṣeto afikun ti a nilo. Ṣẹda/ṣe atunṣe faili .htaccess ninu folda uploads (ati ninu folda akọkọ fun multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'N jẹ ki Membership Ẹgbẹ Igbani jẹ ti a fi akoko le (idaduro ati/tabi iṣeto fun ipari). UI olutọsọna ọjọ rọrun lẹgbẹẹ yiyan membership ẹgbẹ.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Ṣẹda tabi mu awọn ifiweranṣẹ pọ lati ba awọn olumulo mu. Ti a ṣe apẹrẹ fun awọn plugin Team / Staff, ṣugbọn pẹlu agbara lilo ti o gbooro.','If you like %s, please leave us a %s rating. Thank you!'=>'Tí o bá fẹ́ %s, jọwọ fi wa %s ìkànsí. Ẹ ṣéun!','About PublishPress Permissions'=>'Nipa PublishPress Àṣẹ','About'=>'Nipa','Permissions Documentation'=>'Iwe ẹtọ','Documentation'=>'Iwe-ẹkọ','Contact the PublishPress team'=>'Kan si ẹgbẹ PublishPress','Contact'=>'Kan si','Permission Group'=>'Ẹgbẹ Ẹtọ','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Awọn Igbanilaaye Pataki: awọn ihamọ (\'Ti dènà\') ni o ni pataki ju awọn afikun (\'Ti mu ṣiṣẹ\') lọ.','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Aṣẹ Pataki: ko si ihamọ (\'Ti dènà\') ti a le lo si awọn ẹgbẹ ti a ṣe apẹrẹ aṣa','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Iṣẹ afikun ti awọn ipa ti wa fun {All} ati {Anonymous} metagroups','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Gba {All} ati {Anonymous} metagroups laaye lati gba awọn aṣẹ kika pato fun akoonu ikọkọ','Users who have specific editing permissions for a post or attachment can also delete it'=>'Awọn olumulo ti o ni awọn aṣẹ ṣiṣatunkọ pato fun ifiweranṣẹ tabi asopọ le tun pa a','Users who have custom editing permissions for an attachment can also delete it'=>'Awọn olumulo ti o ni awọn aṣẹ ṣiṣatunkọ aṣa fun asopọ le tun pa a','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'Dena sisọ àwárí iwaju ti olumulo ti a forukọsilẹ ba jẹ alakoso akoonu (ni deede, lọtọ lati jẹ ki a fi awọn ifiweranṣẹ ikọkọ ti a ka sinu akojọ get_pages(), nọmba ifiweranṣẹ, ati bẹbẹ lọ.','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'Dena sisọ àwárí iwaju fun gbogbo awọn olumulo (da lori ihamọ nipasẹ PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Akojọ ti awọn iru ifiweranṣẹ ti a ya sọtọ nipasẹ koma lati dinku ipa ti PP_UNFILTERED_FRONT ati apply_filters( \'presspermit_skip_cap_filtering\' )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Aṣẹ Pataki: awọn afikun (\'Ti muu ṣiṣẹ\') ko ni lo, ko le yàn','Don\'t assign or apply specific permissions for the \'post\' type'=>'Maṣe yan tabi lo ẹtọ pato fun iru \'post\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'Maṣe yan tabi lo ẹtọ pato fun iru \'page\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'Maṣe yan tabi lo ẹtọ pato fun iru \'media\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'Maṣe yàn tabi lo awọn aṣẹ pato fun iru ifiweranṣẹ aṣa ti a sọ','Include scheduled posts in the posts query if user can edit them'=>'Fi awọn ifiweranṣẹ ti a ṣe eto sinu ibeere awọn ifiweranṣẹ ti olumulo ba le satunkọ wọn','Don\'t filter term post counts in get_terms() call'=>'Ma ṣe lọtọ awọn iye ifiweranṣẹ ọrọ ni ipe get_terms()','Leave unreadable posts on WP Navigation Menus'=>'Fi awọn ifiweranṣẹ ti ko ka silẹ lori awọn akojọ aṣayan lilọ kiri WP','Don\'t apply CSS to hide empty Nav Menus'=>'Ma ṣe lo CSS lati pa awọn akojọ aṣayan Nav ofo','For legacy Nav Menus, hide empty nav menu div'=>'Fun awọn akojọ aṣayan Nav atijọ, pa div akojọ aṣayan nav ofo','Leave terms with no readable posts on WP Navigation Menus'=>'Fi awọn ọrọ ti ko ni ifiweranṣẹ ti a le ka silẹ lori awọn akojọ aṣayan lilọ kiri WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Nigbati a ba lo Teaser pẹlu Atunṣe ti o mu, fi URL atilẹba kun gẹgẹbi argumento redirect_to','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'Fun ibamu Teaser, yan argumento atunṣe lati lo dipo redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'Fun ibamu Teaser, yan argumento atunṣe afikun ju redirect_to lọ','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'Fun ibamu Teaser, dena argumento pp_permissions lati wa ni fi kun si awọn atunṣe','Filter priority for \'get_pages\' filter (default: 1)'=>'Filter priority fun \'get_pages\' filter (aiyipada: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'Maṣe fi awọn oju-iwe ikọkọ ti a ka sinu ẹrọ àwárí Awọn Oju-iwe tabi awọn abajade wp_list_pages() / get_pages()    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Ti diẹ ninu awọn oju-iwe ti wa ni dena lati awọn abajade get_pages(), yi awọn iye post_parent ti awọn oju-iwe ọmọ pada si ante ti o han','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Maṣe yi iye post_parent pada ninu akojọ abajade get_pages(), paapaa ti diẹ ninu awọn oju-iwe ti wa ni dena','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'Fun iṣẹ ṣiṣe, yi ibeere ile-ikawe get_pages() pada lati da pada nikan ni subset ti awọn aaye, ko ka post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Maṣe lo teaser akoonu si awọn abajade get_pages() (fi awọn ifiweranṣẹ ti a ko ka pamọ)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Ti diẹ ninu awọn ọrọ ti wa ni dena lati awọn abajade get_terms(), yi awọn iye obi ti awọn ọrọ ọmọ pada si ante ti o han','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Maṣe yi iye obi pada ninu akojọ abajade get_terms(), paapaa ti diẹ ninu awọn ọrọ ti wa ni dena','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Ṣeto Onkọwe si olumulo lọwọlọwọ ti a ti fi agbara autoset_post_author / autoset_page_author silẹ','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Fi Ile-ikawe Media silẹ pẹlu awọn ilana wiwọle deede da lori awọn agbara ipa olumulo\'s ','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'Gba awọn solusan gbigba awọn oju-iwe niwaju ti o nilo awọn agbara ṣiṣatunkọ oju-iwe fun ibeere gbigba async','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Tọju media ti o so pọ pẹlu awọn iru ifiweranṣẹ ti ko forukọsilẹ gẹgẹbi ti ko so, lati yago fun asẹ ti ko tọ ati ti o nira','Attached Files Private setting available'=>'Iwọn eto ikọkọ ti awọn faili ti a so pọ wa','Comma-separated list of mime types to exclude from File Access filtering'=>'Atokọ ti awọn iru mime ti a ya sọtọ nipasẹ kóma lati yọkuro ninu iṣ filtering wiwọle faili','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Atokọ ti awọn iru mime ti a ya sọtọ nipasẹ koma lati fi kun ninu asẹ wiwọle Faili (ti o yago fun awọn miiran)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Nigbati wiwọle faili ba ti dina, ma ṣe ṣeto ohun-ini WP_Query 404 / 403','HTTP status code to send when file access is blocked'=>'Koodu ipo HTTP lati fi ranṣẹ nigbati wiwọle faili ba ti dina','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'Lori atokọ Awọn olumulo, Awọn ẹgbẹ Aṣẹ ninu ọwọn aṣa jẹ awọn ọna asopọ asẹ atokọ dipo awọn ọna asopọ ṣiṣatunkọ ẹgbẹ','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'Tu Aṣẹ silẹ > Eto > Core > Iṣakoso Ẹhin > \'Tẹ awọn ifiweranṣẹ ti ko le ṣe atunṣe\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'Ninu iwe afọwọkọ async-upload.php, asẹ gbigba onkọwe\'s ti awọn asopọ ti wọn kan gbe wọle','Don\'t filter comment display or moderation within wp-admin'=>'Ma ṣe àlẹmọ ifihan ikọkọ tabi iṣakoso laarin wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Gba awọn Alakoso laaye lati wa ni afikun si Awọn ẹgbẹ Aṣẹ, paapaa nigba ti wọn ko ni ihamọ','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Ti awọn aṣẹ ikolu ba ti fi silẹ si ẹka oju-iwe kan, kọja eyikeyi awọn aṣẹ ti a fi silẹ ni kedere ni awọn oju-iwe kekere','Max number of specific permissions to insert in a single database query (default 1000)'=>'Iye ti o pọ julọ ti awọn aṣẹ pato lati fi sinu ibeere ibi ipamọ data kan (aiyipada 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Ma ṣe yipada awọn itọka akojọ aṣayan alakoso lati gbe akojọ aṣayan Awọn Aṣẹ labẹ Awọn olumulo','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Ma ṣe fi akojọ aṣayan Aṣẹ kun. Dipo, fi awọn ohun akojọ kun si awọn akojọ aṣayan Awọn olumulo ati Eto.','Customize Permissions screen title for Groups'=>'Ṣatunkọ akọle iboju Awọn Aṣẹ fun Awọn Ẹgbẹ','Customize Permission Groups caption on user profile'=>'Ṣatunkọ akọle Awọn Ẹgbẹ Aṣẹ lori profaili olumulo','Only one group is selectable on Add User screen'=>'Ẹgbẹ kan ṣoṣo ni a le yan lori iboju Fi Ẹnikan Kun','Only one group is selectable on Edit User screen'=>'Ẹgbẹ kan ṣoṣo ni a le yan lori iboju Ṣatunkọ Ẹnikan','Display a custom hint on Permissions > User Groups'=>'Ṣafihan ìmọ̀ràn àdáni lórí Àṣẹ > Awọn Ẹgbẹ Olumulo','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Iye ti o pọ julọ ti awọn ifiweranṣẹ / awọn ọrọ ti ko ni ilana lati han ni akoko kan (ni ibẹrẹ oju-iwe)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Iye to pọ julọ ti awọn ifiweranṣẹ / awọn ọrọ hierarchical lati ṣafihan ni akoko kan (lẹta oju-iwe)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'Dena idanimọ laifọwọyi ti bi ọpọlọpọ awọn ipele ti igi oju-iwe lati jẹ ki o han nipasẹ aiyipada. Dipo, lo iye ti a sọ.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Iye ti a fojusi ti awọn oju-iwe / awọn ọrọ ti o han, ti a lo fun idanimọ laifọwọyi ti nọmba awọn ipele ti o han','Make search function on the post selection metabox look at post content'=>'Ṣe iṣẹ àwárí lori apoti yiyan ifiweranṣẹ wo akoonu ifiweranṣẹ','Make search function on the post selection metabox look at post excerpt'=>'Ṣe iṣẹ àwárí lori apoti yiyan ifiweranṣẹ wo akopọ ifiweranṣẹ','Search by last name instead of display name'=>'Wá nipa orukọ idile dipo orukọ ifihan','User field to search by default'=>'Ibi olumulo lati wa nipa aiyipada','User meta fields selectable for search (comma-separated)'=>'Awọn aaye meta olumulo ti o le yan fun àwárí (pẹlu koma)','User meta fields which should be treated as numeric (comma-separated)'=>'Awọn aaye meta olumulo ti a gbọdọ ṣe itọju gẹgẹbi nọmba (pẹlu koma)','User meta fields which should be treated as boolean (comma-separated)'=>'Awọn aaye meta olumulo ti a gbọdọ ṣe itọju gẹgẹbi boolean (pẹlu koma)','Use display name for search results instead of user_login'=>'Lo orukọ ifihan fun awọn abajade àwárí dipo user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'Nigbati o ba n ṣepọ awọn ẹgbẹ metagroups ipa si awọn ipa WP ti a ṣe alaye lọwọlọwọ, maṣe pa awọn ẹgbẹ fun awọn ipa WP ti a ti ṣalaye tẹlẹ.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Fi agbara mu idanimọ awọn ipa olumulo WP ti a ti fi kun ni dinamik ṣugbọn ko ti fipamọ si ibi ipamọ data WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'Lati fipamọ iranti lori wiwọle iwaju, ma ṣe forukọsilẹ eyikeyi awọn asẹ ti o ni ibatan si ṣiṣatunkọ akoonu','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'Media ti a so ko ni awọn asọye eyikeyi, nitorinaa maṣe fi awọn ipese kun si awọn ibeere asọye fun wọn','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'Dinku inawo ti ibeere oju-iwe (ni get_pages() ati wp-admin) nipa titunṣe awọn aaye si atokọ ti a ṣeto ti ko ni post_content ','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'Dinku iṣẹ́ àkóso ti wp-admin posts ìbéèrè nípa ṣiṣé àtúnṣe àwọn àgbékalẹ̀ sí àkójọpọ̀ kan tí kò ní post_content ','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'Dinku iṣẹ́ àkóso ti wp-admin Media ìbéèrè nípa ṣiṣé àtúnṣe àwọn àgbékalẹ̀ sí àkójọpọ̀ kan tí kò ní post_content ','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'Dinku iṣẹ́ àkóso ti wp-admin ìbéèrè fún irú àtúnṣe àtọkànwá tí a tọka sí nípa ṣiṣé àtúnṣe àwọn àgbékalẹ̀ sí àkójọpọ̀ kan tí kò ní post_content ','Work around database setup warnings (at plugin activation) on some servers'=>'Ṣe iṣẹ-ṣelọpọ ayẹwo awọn ikilọ eto ibi ipamọ data (ni iṣ activation plugin) lori diẹ ninu awọn olupin','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'Ìlò ìdàgbàsókè nikan (fi ẹ̀sùn post_status = \'publish\' pamọ́ fún àwọn irú àtúnṣe tí a ko lọ́ọkàn pẹ̀lú olumulo àìmọ̀)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'Ìlò ìdàgbàsókè nikan (ní iwájú, má ṣe rọ́pò \'post_status = \'publish\'\' ẹ̀sùn pẹ̀lú àtúnṣe tó lọ́ọkàn)','Logged In'=>'Ti wọle','Not Logged In'=>'Ko ti wọle','Everyone'=>'Gbogbo eniyan','Change Request Notifications'=>'Awọn ifitonileti ibeere ayipada','Submitted Revision Editors'=>'Ìtúnṣe Tí a Fí Kà','Scheduled Change Notifications'=>'Awọn ifitonileti ayipada ti a ṣeto','Scheduled Revision Monitors'=>'Awọn olutọpa atunṣe ti a ṣeto','Authenticated site users, except for Administrators'=>'Awọn olumulo aaye ti a jẹrisi, ayafi fun Awọn Alakoso','Anonymous users (not logged in)'=>'Awọn olumulo aibikita (ko ti wọle)','All users (including anonymous)'=>'Gbogbo awọn olumulo (pẹlu aibikita)','All users with the WordPress role of %s'=>'Gbogbo awọn olumulo pẹlu ipa WordPress ti %s','%1$s %2$s'=>'%1$s %2$s','%1$s won&#39;t work until you upgrade PHP to version %2$s or later. Current version: %3$s'=>'%1$s kò&#39;t ṣiṣẹ́ titi di igba ti o bá ṣe àtúnṣe PHP sí version %2$s tàbí ti ẹlòmíì. Version to wa: %3$s','%1$s won&#39;t work until you upgrade %2$s to version %3$s or later.'=>'%1$s ko&#39;t ṣiṣẹ titi iwọ o fi ṣe imudojuiwọn %2$s si ẹya %3$s tabi lẹhin.','%1$s won&#39;t work until you upgrade WordPress to version %2$s or later.'=>'%1$s ko&#39;t ṣiṣẹ titi iwọ o fi ṣe imudojuiwọn WordPress si ẹya %2$s tabi lẹhin.','This version of %1$s cannot work with your current %2$s version. Please upgrade it to %3$s or later.'=>'Ìtúpalẹ̀ yìí ti %1$s kò le ṣiṣẹ́ pẹ̀lú version %2$s rẹ̀. Jọwọ ṣe àtúnṣe rẹ̀ sí %3$s tàbí ti ẹlòmíì.','Duplicate %1$s module activated (%2$s in folder %3$s).'=>'Modulu %1$s ti a tunṣe ti ṣiṣẹ (%2$s ninu folda %3$s).','Dismiss'=>'Kó','Custom Group'=>'Ẹgbẹ Aṣ Customized','Custom Groups'=>'Awọn Ẹgbẹ Aṣ Customized','Groups'=>'Awọn Ẹgbẹ','(using default capabilities due to invalid %s definition)'=>'(nlo awọn agbara aiyipada nitori %s itumọ ti ko tọ)','%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s'=>'%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s','%1$s&nbsp;%2$s%3$s'=>'%1$s&nbsp;%2$s%3$s','Your license key has expired. For updates to PublishPress Permissions Pro and priority support, %splease renew%s.'=>'Bọtini ìwé-aṣẹ rẹ ti parẹ. Fun ìmúdájúpọ̀ sí PublishPress Permissions Pro àti atilẹyin pataki, %s jọwọ tún ṣe %s.','[WP %s]'=>'[WP %s]','All users with a WordPress %s role'=>'Gbogbo awọn olumulo pẹlu ipa WordPress %s','All users who are logged in and have a role on the site'=>'Gbogbo awọn olumulo ti o ti wọle ati pe wọn ni ipa lori aaye naa','Users to notify when revisions are submitted'=>'Awọn olumulo lati jẹ ki a mọ nigbati awọn atunṣe ba ti fi silẹ','Users to notify when scheduled revisions are published'=>'Awọn olumulo lati jẹ ki a mọ nigbati awọn atunṣe ti a ṣe eto ba ti tẹjade','(login timed out)'=>'(iṣaaju ikọkọ ti pari)','View'=>'Wo','Control assignment of selected terms to %s.'=>'Ṣakoso pinpin awọn ọrọ ti a yan si %s.','Control if this %s can be selected as a Parent Page.'=>'Ṣakoso ti %s yii le jẹ yiyan gẹgẹ bi Ojú-iwe Iya.','Control editing of selected %s.'=>'Ṣakoso ṣiṣatunkọ ti %s ti a yan.','Control publishing of selected %s.'=>'Ṣakoso ikede ti %s ti a yan.','Control deletion of selected %s.'=>'Ṣakoso piparẹ ti %s ti a yan.','Control term management for selected %s.'=>'Ṣakoso iṣakoso ọrọ fun %s ti a yan.','Control frontend viewing of selected %s.'=>'Ṣakoso wiwo iwaju ti %s ti a yan.','Control who can create a revision of this %s.'=>'Ṣakoso ẹni tí ó lè dá àtúnṣe ti %s yìí sílẹ̀.','Control who can submit a revision of this %s.'=>'Ṣakoso ẹni tí ó lè fi àtúnṣe ti %s yìí sílẹ̀.','Control which terms can be set as a Parent of other terms.'=>'Ṣakoso awọn ọrọ wo ni a le ṣeto gẹgẹbi Ọmọde ti awọn ọrọ miiran.','Allow users to manage selected terms.'=>'Gba awọn olumulo laaye lati ṣakoso awọn ọrọ ti a yan.','Control management of selected groups.'=>'Ṣakoso iṣakoso ti awọn ẹgbẹ ti a yan.','Enable'=>'Mu ṣiṣẹ','Block'=>'Dena','Limit to'=>'Iwọn si','Expand access to allow specified items regardless of role capabilities or restrictions.'=>'Fa àfihàn pọ̀ sí i láti jẹ́ kí àwọn ohun tí a tọka sí ní wọlé láìka agbara ipa tàbí ìdènà.','Restrict access by blocking specified items unless an "Enabled" exception is also stored.'=>'Dènà àfihàn nipa didín àwọn ohun tí a tọka sí ayafi pé àpẹẹrẹ "Enabled" tún ti fipamọ́.','Restrict access by limiting role capabilities to apply only for specified items. Users still need capabilities in their main role or extra roles.'=>'Dènà àfihàn nipa didín agbara ipa sí i lati lo fún àwọn ohun tí a tọka sí. Àwọn olumulo ṣi nilo agbara ní ipa wọn àkọ́kọ́ tàbí àwọn ipa afikun.','Using group membership to block access is not recommended. Consider reducing the user\'s role capabilities and using group membership to add access.'=>'Lilo ìṣeduro ẹgbẹ́ láti dènà àfihàn kò jẹ́ ohun tó dára. Ronú pẹ̀lú dín agbara ipa olumulo àti lilo ìṣeduro ẹgbẹ́ láti fi àfihàn kun.','Selected:'=>'Ti a yan:','Nav Menus (Legacy)'=>'Awọn akojọ aṣayan Nav (Iwa atijọ)','Legacy'=>'Iwa atijọ','%s:'=>'%s:','Selected %s:'=>'Ti a yan %s:','Sub-%s:'=>'Sub-%s:','All Statuses'=>'Gbogbo Awọn ipo','%s Visibility'=>'%s Wiwo','No user/group specified.'=>'Ko si olumulo / ẹgbẹ ti a sọ.','You are not permitted to do that.'=>'Iwọ ko ni aṣẹ lati ṣe iyẹn.','Invalid user ID.'=>'ID olumulo ti ko tọ.','Invalid group ID.'=>'ID ẹgbẹ ti ko tọ.','Roles updated.'=>'Awọn ipa ti ni imudojuiwọn.','Specific Permissions updated.'=>'Awọn Iwe-aṣẹ pato ti ni imudojuiwọn.','Roles and Permissions copied.'=>'Awọn ipa ati Awọn Iwe-aṣẹ ti daakọ.','Group updated.'=>'Ìkànsí ẹgbẹ́.','Back to permissions list'=>'Padà sí àkójọ ìfọwọ́sí','Edit User Permissions'=>'Ṣatunkọ Àṣẹ Olumulo','Add User Permissions'=>'Fikun Àṣẹ Olumulo','Edit Permissions'=>'Ṣatunkọ Àṣẹ','Edit Permissions (%s)'=>'Ṣatunkọ Àṣẹ (%s)','%sEdit WordPress Role%s'=>'%sṢatunkọ Role WordPress%s','Edit role capabilities directly'=>'Ṣatunkọ agbara ipa taara','Add New'=>'Fikun Tuntun','Name:'=>'Orukọ:','Email:'=>'Ìmélì:','Primary Role:'=>'Ipa Pataki:','User ID:'=>'ID Olumulo:','Member since:'=>'Ẹni tó wà lára:','Description:'=>'Àpejuwe:','Update Permissions'=>'Ìmúdàgba Àṣẹ','View Full Profile'=>'Wo Profaili Gbogbo','Extra Roles %1$s(from primary role or %2$sgroup membership%3$s)%4$s'=>'Awọn ipa afikun %1$s(lati ipa akọkọ tabi %2$sbí ẹgbẹ%3$s)%4$s','Specific Permissions %1$s(from primary role or %2$sgroup membership%3$s)%4$s'=>'Iwọle pato %1$s(lati ipa akọkọ tabi %2$sbí ẹgbẹ%3$s)%4$s','View currently stored user permissions:'=>'Wo àṣẹ awọn olumulo ti a fipamọ́ lọwọlọwọ:','%1$sUsers who have Extra Roles assigned directly%2$s'=>'%1$sÀwọn olumulo tí a ti fún ni Ipa Àfikún taara%2$s','%1$sUsers who have Specific Permissions assigned directly%2$s'=>'%1$sÀwọn olumulo tí a ti fún ni Àṣẹ Pataki taara%2$s','%1$sUsers who have Extra Roles or Specific Permissions directly%2$s'=>'%1$sAwọn olumulo ti o ni Awọn ipa afikun tabi Awọn igbanilaaye pato taara%2$s','Add Roles'=>'Fi Awọn ipa kun','Clear'=>'Ko','No statuses selected!'=>'Ko si ipo ti a yan!','Review the selection below, and then click <strong>Save Roles</strong>.'=>'Ṣayẹwo yiyan ni isalẹ, lẹhinna tẹ <strong>Fipamọ Awọn ipa</strong>.','Role already selected!'=>'Ipa ti yan tẹlẹ!','No Action selected!'=>'Ko si Iṣe ti a yan!','Saving Roles...'=>'Nṣiṣẹ Awọn ipa...','Reload form for further changes to this role'=>'Tun awọn fọọmu ṣe fun awọn ayipada si ipa yii','Show Groups'=>'Fihan Awọn ẹgbẹ','Hide Groups'=>'Tọju Awọn Ẹgbẹ','Add Specific Permissions'=>'Fi Awọn igbanilaaye pato kun','Remove'=>'Yọ','Review the selection below, and then click <strong>Save Permissions</strong>.'=>'Ṣàyẹ̀wò àṣàyàn ní isalẹ, kí o sì tẹ <strong>Fipamọ́ Àṣẹ</strong>.','Permission already selected!'=>'Igbamọ ti yan tẹlẹ!','Saving Permissions...'=>'Nṣiṣẹ Awọn igbanilaaye...','Reload form for further changes to this permission'=>'Tun awọn fọọmu ṣe fun awọn ayipada si igbanilaaye yii','Permissions mirrored. Reload form to view newly saved permissions.'=>'Awọn igbanilaaye ti ṣe afihan. Tun awọn fọọmu ṣe lati wo awọn igbanilaaye ti a fipamọ laipẹ.','Permissions converted. Reload form to view newly saved permissions.'=>'Awọn igbanilaaye ti yipada. Tun awọn fọọmu ṣe lati wo awọn igbanilaaye ti a fipamọ laipẹ.','No Qualification selected!'=>'Ko si Iwe-ẹri ti a yan!','No items selected!'=>'Ko si awọn nkan ti a yan!','(no parent)'=>'(ko si baba)','(none)'=>'(ko si)','No results found.'=>'Ko si awọn abajade ti a ri.','select...'=>'yan...','Nav Menu (Block)'=>'Àtọọ́ka Àtúnṣe (Blọ́kì)','All Post Types'=>'Gbogbo Irú Ifiweranṣẹ','n/a'=>'n/a','Post Type'=>'Irú Ifiweranṣẹ','Operation'=>'Iṣẹ','Adjustment'=>'Àtúnṣe','Qualification'=>'Ìmúrasílẹ̀','Statuses'=>'Ipo','for item'=>'fun nkan','Warning: Content hidden by these Permissions will be displayed if PP is deactivated. Consider setting a private Visibility on Edit Post screen instead.'=>'Ikilọ: Àkópọ̀ tí a pamọ́ nipasẹ Àṣẹ wọ̀nyí yóò hàn bí PP ba ti dákẹ́. Ronú pẹ̀lú ṣíṣe àtọkànwá àfihàn àkọ́kọ́ ní iboju Ṣatunkọ Àtúnṣe dipo.','To assign page-specific Permissions for editing, parent selection or term assignment, enable the Editing Permissions feature.'=>'Láti assign àṣẹ pàtó ojúewé fún ṣiṣatunkọ, àṣàyàn ìyá tàbí ìpinnu àkópọ̀, ṣe àfihàn ẹya Àṣẹ Ṣatunkọ.','To assign forum-specific Permissions for bbPress, activate the Compatibility Pack feature.'=>'Láti assign àṣẹ pàtó fún bbPress, ṣiṣé ẹya Compatibility Pack.','To assign forum-specific Permissions for bbPress, %1$supgrade to Permissions Pro%2$s and enable the Compatibility Pack feature.'=>'Láti assign àṣẹ pàtó fún bbPress, %1$s ṣe àtúnṣe sí Permissions Pro %2$s àti ṣiṣé ẹya Compatibility Pack.','Role'=>'Ipa','For Statuses'=>'Fun Ipo','Standard statuses'=>'Ipo boṣewa','Status: Private'=>'Ipo: Ikọkọ','Add Role'=>'Fikun Role','To assign roles for bbPress forums, activate the Compatibility Pack feature.'=>'Lati yan awọn ipa f